<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {useQuery,useQueryClient} from '@tanstack/vue-query';
import {request} from '../../api/client';
import {permissions,message} from '../sites/data';
import {type Resource,type Config,labels,title,when} from './contracts';
const props=defineProps<{kind:string}>(),{isAdmin}=permissions(),client=useQueryClient();
const query=useQuery({queryKey:computed(()=>['pki-resources',props.kind]),queryFn:()=>request<{items:Resource[]}>('/certificates/'+props.kind),staleTime:0,refetchOnWindowFocus:true});
function clearSecrets(){secret.value='';pem.value='';code.value=''}
onMounted(()=>window.addEventListener('pagehide',clearSecrets));onUnmounted(()=>{clearSecrets();window.removeEventListener('pagehide',clearSecrets)})
const items=computed(()=>query.data.value?.items||[]),editing=ref(false),id=ref(''),revision=ref(0),config=ref<Config>({}),names=ref(''),credentials=ref<string[]>([]),code=ref(''),secret=ref(''),pem=ref(''),busy=ref(false),error=ref(''),notice=ref('');
const accounts=useQuery({queryKey:['pki-resources','account'],queryFn:()=>request<{items:Resource[]}>('/certificates/account'),enabled:computed(()=>props.kind==='spec')});
const credentialOptions=useQuery({queryKey:['pki-resources','credential'],queryFn:()=>request<{items:Resource[]}>('/certificates/credential'),enabled:computed(()=>props.kind==='spec')});
const trusts=useQuery({queryKey:['pki-resources','trust'],queryFn:()=>request<{items:Resource[]}>('/certificates/trust'),enabled:computed(()=>props.kind==='spec')});
function edit(r?:Resource){id.value=r?.id||'';revision.value=r?.revision||0;config.value=r?JSON.parse(JSON.stringify(r.body)):props.kind==='spec'?{purpose:'serverAuth',method:'acme',challenge:'http-01',provider_id:''}:props.kind==='account'?{provider:'letsencrypt',email:''}:props.kind==='credential'?{zone_id:'',zone_name:''}:{purpose:'clientAuth',status_profile:'',origin_pull_authorized:false};names.value=config.value.names?.join('\n')||'';credentials.value=config.value.credential_ids||[];secret.value='';pem.value='';code.value='';editing.value=true;error.value='';notice.value=''}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn();await client.invalidateQueries({queryKey:['pki-resources']})}catch(e){error.value=message(e)}finally{busy.value=false;code.value='';secret.value='';pem.value=''}}
function save(){void perform(async()=>{
 const body:Config=JSON.parse(JSON.stringify(config.value));
 if(props.kind==='spec'){body.names=names.value.split(/[\s,]+/).filter(Boolean);if(body.method==='import'){delete body.provider_id;delete body.challenge;delete body.credential_ids}else body.credential_ids=body.challenge==='dns-01'?credentials.value:[];if(body.trust_id){body.trust_revision=(trusts.data.value?.items||[]).find(r=>r.id===body.trust_id)?.revision}else{delete body.trust_id;delete body.trust_revision}}
 const out=await request<Resource>('/certificates/'+props.kind+(id.value?'/'+id.value:''),{expected_revision:revision.value,config:body,secret:secret.value,pem:pem.value,totp_code:code.value},id.value?'PUT':'POST');id.value=out.id;revision.value=out.revision;editing.value=false;notice.value='已保存并启用；网络准备由后台执行，生效须查看发布与实际运行结果。'
})}
function toggle(r:Resource){void perform(async()=>{await request('/certificates/'+props.kind+'/'+r.id+'/enabled',{expected_revision:r.revision,enabled:!r.enabled,totp_code:code.value});notice.value='启用状态已提交；不等同于证书吊销或网关已生效。'})}
</script>
<template><section class="panel" :data-testid="'resources-'+kind"><div class="section-heading"><h2>{{labels[kind]}}</h2><button :disabled="!isAdmin||busy" @click="edit()">新建{{labels[kind]}}</button></div>
<p v-if="error||query.error.value" role="alert">{{error||message(query.error.value)}}</p><p v-if="notice" role="status">{{notice}}</p>
<button :disabled="query.isFetching.value" @click="query.refetch()">刷新{{labels[kind]}}</button>
<p v-if="!items.length&&!query.isPending.value">没有当前可完整查看的资源（最多 1000 项）。</p>
<label v-if="isAdmin">操作动态验证码<input v-model="code" type="password" autocomplete="off" inputmode="numeric" maxlength="6"></label>
<article v-for="r in items" :key="r.id" class="subpanel" :data-testid="'resource-'+r.id"><h3>{{title(r)}}</h3><p class="mono">{{r.id}} · 修订 {{r.revision}}</p><p>{{r.enabled?'已启用':'已停用'}} · {{r.lifecycle.preparing?'正在准备':'无进行中准备'}} · 准备失败 {{r.lifecycle.preparation_failures}} · 下次准备 {{when(r.lifecycle.preparation_next_attempt)}}</p>
<p v-if="kind==='spec'">当前管理修订 {{r.revision}} · 当前存储版本 {{r.lifecycle.current_version||'尚未就绪'}} · 续期失败 {{r.lifecycle.failures}} · 下次重试 {{when(r.lifecycle.next_attempt)}}</p>
<p v-for="state in r.lifecycle.revisions||[]" :key="state.revision" :data-testid="'revision-lifecycle-'+r.id+'-'+state.revision">规格修订 {{state.revision}} · {{state.revision===r.revision?'当前管理修订':'历史修订'}}{{r.lifecycle.active?.some(a=>a.spec_revision===state.revision)?' / 当前已验证绑定':''}} · 续期失败 {{state.failures}} · 下次重试 {{when(state.next_attempt)}} · {{state.preparing?'正在续期':'无进行中续期'}}</p>
<p v-if="kind==='spec'&&!r.lifecycle.active?.length" class="muted">实际绑定：尚无当前网关验证回执。</p>
<div v-for="a in r.lifecycle.active||[]" :key="a.artifact_id" data-testid="active-binding"><p>实际已加载版本 {{a.version_id}} · 规格修订 {{a.spec_revision}}</p><p>应用制品 {{a.artifact_id}} · 运行版本 {{a.version}} · 确认 {{when(a.verified_at)}}</p><p>{{a.version_id===r.lifecycle.current_version&&a.spec_revision===r.revision?'当前存储版本已实际加载':'历史规格/版本仍生效，当前存储版本尚未确认加载'}}</p></div>
<button :disabled="!isAdmin||busy" @click="edit(r)">编辑{{labels[kind]}}新修订</button> <button :disabled="!isAdmin||busy||code.length!==6" @click="toggle(r)">{{r.enabled?'停用':'启用'}}{{labels[kind]}}</button>
<details><summary>授权元数据</summary><pre>{{JSON.stringify(r.body,null,2)}}</pre></details>
<div v-for="v in r.lifecycle.versions" :key="v.id" class="subpanel"><p>版本 {{v.id}} · 规格修订 {{v.spec_revision}} · {{v.id===r.lifecycle.current_version?'当前存储版本':'历史版本'}}</p><p>{{v.names.join(', ')}} · {{v.purpose}} · 颁发者 {{v.issuer}}</p><p>有效期 {{when(v.not_before)}} 至 {{when(v.not_after)}} · {{v.automatic?'自动续期':'手动导入，无自动续期'}}</p></div>
</article>
<form v-if="editing" @submit.prevent="save" class="subpanel"><h3>{{id?'编辑新修订':'创建并启用'}}{{labels[kind]}}</h3><p v-if="id">修订 {{revision}} 的替换需要重新审阅和人工发布。</p><fieldset :disabled="busy||!isAdmin"><div class="form-grid">
<template v-if="kind==='spec'"><label>证书名称（每行一个 DNS 名）<textarea v-model="names" required/></label><label>证书用途<select v-model="config.purpose"><option value="serverAuth">服务器身份 serverAuth</option><option value="clientAuth">客户端身份 clientAuth</option></select></label><label>管理方式<select v-model="config.method"><option value="acme">标准 ACME 自动续期</option><option value="import">手动导入</option></select></label><template v-if="config.method==='acme'"><label>CA 账号<select v-model="config.provider_id" required><option value="">请选择授权账号</option><option v-for="a in accounts.data.value?.items||[]" :key="a.id" :value="a.id">{{title(a)}} · {{a.enabled?'已启用':'已停用'}}</option></select></label><label>标准验证<select v-model="config.challenge"><option value="http-01">HTTP-01</option><option value="dns-01">DNS-01</option></select></label><fieldset v-if="config.challenge==='dns-01'"><legend>Cloudflare 多凭据（只可选授权区域）</legend><label v-for="c in credentialOptions.data.value?.items||[]" :key="c.id"><input type="checkbox" v-model="credentials" :value="c.id">{{title(c)}}</label></fieldset></template><label>信任包<select v-model="config.trust_id"><option :value="undefined">公共系统信任</option><option v-for="t in trusts.data.value?.items||[]" :key="t.id" :value="t.id">{{title(t)}} · 修订 {{t.revision}}</option></select></label></template>
<template v-if="kind==='account'"><label>CA 机构<select v-model="config.provider"><option value="letsencrypt">Let's Encrypt</option><option value="zerossl">ZeroSSL</option><option value="google">Google Trust Services</option><option value="internal-server">内部服务器 ACME</option><option value="internal-client">内部客户端 ACME</option></select></label><label>联系邮箱<input type="email" v-model="config.email" required></label><label>EAB Key ID<input v-model="config.eab_key_id" autocomplete="off"></label><label>新 EAB HMAC（仅提交，不回显）<input v-model="secret" type="password" autocomplete="new-password" :required="config.provider!=='letsencrypt'"></label><p>内部目录由 trusted ca_origin 固定，先人工授权并生成一次性 EAB。更改账号会创建新私密账号材料。</p></template>
<template v-if="kind==='credential'"><label>Cloudflare Zone ID<input v-model="config.zone_id" minlength="32" maxlength="32" pattern="[a-f0-9]{32}" required></label><label>区域域名<input v-model="config.zone_name" required></label><label>新 Cloudflare API Token<input v-model="secret" type="password" autocomplete="new-password" required maxlength="4096"></label><p>仅用于已声明区域的 DNS-01；支持多个区域凭据。已有 Token 永不回显。</p></template>
<template v-if="kind==='trust'"><label>信任用途<select v-model="config.purpose"><option value="clientAuth">客户端验证 clientAuth</option><option value="serverAuth">上游验证 serverAuth</option></select></label><label>信任 PEM<textarea v-model="pem" required/></label><label>受信状态配置名称<input v-model="config.status_profile" required></label><label><input v-model="config.origin_pull_authorized" type="checkbox">已人工核对第三方 AOP 授权与云侧配置</label></template>
</div><button type="submit" :disabled="code.length!==6">{{id?'保存新修订并启用':'创建并启用准备'}}</button><button type="button" @click="editing=false;secret='';pem='';code=''">取消并清除秘密</button></fieldset></form>
</section></template>
